<script setup>
import { ref, reactive, computed, onMounted, watch } from 'vue'
import { useQuasar } from 'quasar'
import { useAuth } from '../stores/auth'
import { useCatalogs } from '../stores/catalogs'
import { api, unwrap, errorMessage, fieldErrors } from '../services/api'
import { roles } from '../domain'
import PageHeading from '../components/PageHeading.vue'
import AsyncState from '../components/AsyncState.vue'
const auth=useAuth(), catalog=useCatalogs(), $q=useQuasar(), tab=ref('collections'), items=ref([]), loading=ref(true), error=ref(''), dialog=ref(false), busy=ref(false), editId=ref(null), errors=ref({}), saveError=ref(''), page=ref(1), last=ref(1)
const tabs=computed(()=>[{name:'collections',label:'Colecciones'},{name:'categories',label:'Categorías'},{name:'authors',label:'Autores'},{name:'keywords',label:'Palabras clave'},{name:'licenses',label:'Licencias'},...(auth.isAdmin?[{name:'users',label:'Usuarios y roles'}]:[])])
const form=reactive({})
const columns=computed(()=>[{name:'name',label:'Nombre',field:'name',align:'left'},...(tab.value==='users'?[{name:'email',label:'Correo',field:'email',align:'left'},{name:'roles',label:'Roles',field:r=>r.roles.join(', '),align:'left'},{name:'active',label:'Estado',field:r=>r.is_active?'Activo':'Inactivo',align:'left'}]:[{name:'description',label:tab.value==='authors'?'Afiliación':'Descripción',field:tab.value==='authors'?'affiliation':'description',align:'left'}]),{name:'actions',label:'Acciones',field:'id',align:'right'}])
const required=v=>(Array.isArray(v)?v.length>0:!!v)||'Este campo es obligatorio'
async function load(){loading.value=true;error.value='';try{const {data}=await api.get(`/${tab.value}`,{params:{page:page.value}});items.value=unwrap(data);last.value=data.meta?.last_page||1}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
watch(tab,()=>{page.value=1;load()})
function open(item=null){editId.value=item?.id||null;errors.value={};saveError.value='';for(const key of Object.keys(form))delete form[key];Object.assign(form,{name:item?.name||''});if(tab.value==='users')Object.assign(form,{email:item?.email||'',roles:[...(item?.roles||['depositante'])],is_active:item?.is_active??true,password:'',password_confirmation:''});else if(tab.value==='authors')Object.assign(form,{email:item?.email||'',affiliation:item?.affiliation||'',orcid:item?.orcid||''});else if(tab.value==='keywords'){}else Object.assign(form,{description:item?.description||''});if(tab.value==='licenses')Object.assign(form,{url:item?.url||'',allows_download:item?.allows_download??false});dialog.value=true}
async function save(){busy.value=true;saveError.value='';errors.value={};try{const body={...form};if(tab.value==='users'&&editId.value&&!body.password){delete body.password;delete body.password_confirmation}if(editId.value)await api.put(`/${tab.value}/${editId.value}`,body);else await api.post(`/${tab.value}`,body);dialog.value=false;catalog.loaded=false;await load();if(tab.value==='users'&&editId.value===auth.user.id){auth.ready=false;await auth.restore()}$q.notify({type:'positive',message:'Cambios guardados.'})}catch(e){saveError.value=errorMessage(e);errors.value=fieldErrors(e)}finally{busy.value=false}}
function confirmSave(){if(tab.value==='users'&&editId.value){$q.dialog({title:'Confirmar cambio de cuenta',message:'Los cambios de roles, estado o credenciales afectan el acceso de esta cuenta. ¿Desea guardarlos?',cancel:true,persistent:true}).onOk(save)}else save()}
function remove(item){$q.dialog({title:tab.value==='users'?'Desactivar cuenta':'Eliminar registro',message:tab.value==='users'?`¿Desea desactivar la cuenta de ${item.name}? Se revocarán sus sesiones.`:`¿Desea eliminar «${item.name}»? El servidor impedirá eliminar registros con recursos asociados.`,cancel:true,ok:{label:tab.value==='users'?'Desactivar':'Eliminar',color:'negative'},persistent:true}).onOk(async()=>{busy.value=true;try{await api.delete(`/${tab.value}/${item.id}`);catalog.loaded=false;await load();$q.notify({type:'positive',message:'Operación completada.'})}catch(e){$q.notify({type:'negative',message:errorMessage(e)})}finally{busy.value=false}})}
onMounted(load)
</script>
<template><PageHeading title="Administración del repositorio" subtitle="Mantenga las colecciones, los metadatos y los permisos de las cuentas autorizadas." /><q-tabs v-model="tab" align="left" active-color="primary" indicator-color="primary" inline-label><q-tab v-for="t in tabs" :key="t.name" :name="t.name" :label="t.label" no-caps /></q-tabs><div class="toolbar"><h2>{{ tabs.find(t=>t.name===tab)?.label }}</h2><q-btn color="primary" unelevated icon="add" label="Crear registro" :disable="busy" @click="open()" /></div><AsyncState :loading="loading" :error="error" :empty="!items.length" @retry="load"><q-table flat bordered :rows="items" :columns="columns" row-key="id" :pagination="{rowsPerPage:0}" hide-pagination><template #body-cell-actions="props"><q-td :props="props"><q-btn flat color="primary" label="Editar" :disable="busy" @click="open(props.row)" /><q-btn flat color="negative" :label="tab==='users'?'Desactivar':'Eliminar'" :disable="busy||(tab==='users'&&props.row.id===auth.user.id)" @click="remove(props.row)" /></q-td></template></q-table></AsyncState><div v-if="last>1" class="pagination"><q-pagination v-model="page" :max="last" :max-pages="5" direction-links @update:model-value="load" /></div><q-dialog v-model="dialog" persistent><q-card class="dialog-card"><q-card-section><h2>{{ editId?'Editar':'Crear' }} registro</h2><p v-if="saveError" class="alert" role="alert">{{ saveError }}</p><q-form @submit="confirmSave"><div class="form-grid"><q-input v-model="form.name" outlined label="Nombre *" maxlength="255" :rules="[required]" :error="!!errors.name" :error-message="errors.name" class="full-width-field" /><template v-if="tab==='users'"><q-input v-model="form.email" outlined type="email" label="Correo electrónico *" :rules="[required]" :error="!!errors.email" :error-message="errors.email" class="full-width-field" /><q-select v-model="form.roles" :options="roles" multiple use-chips outlined label="Roles *" :rules="[required]" :error="!!errors.roles" :error-message="errors.roles" class="full-width-field" /><q-input v-model="form.password" outlined type="password" autocomplete="new-password" :label="editId?'Nueva contraseña (opcional)':'Contraseña *'" :rules="[v=>(editId&&!v)||v.length>=8||'Use al menos 8 caracteres']" :error="!!errors.password" :error-message="errors.password" /><q-input v-model="form.password_confirmation" outlined type="password" autocomplete="new-password" label="Confirmar contraseña" :rules="[v=>v===form.password||'Las contraseñas no coinciden']" /><q-toggle v-model="form.is_active" label="Cuenta activa" /></template><template v-else-if="tab==='authors'"><q-input v-model="form.email" outlined type="email" label="Correo electrónico" :error="!!errors.email" :error-message="errors.email" /><q-input v-model="form.orcid" outlined label="ORCID" :error="!!errors.orcid" :error-message="errors.orcid" /><q-input v-model="form.affiliation" outlined label="Afiliación" class="full-width-field" :error="!!errors.affiliation" :error-message="errors.affiliation" /></template><q-input v-else-if="tab!=='keywords'" v-model="form.description" outlined type="textarea" label="Descripción" class="full-width-field" :error="!!errors.description" :error-message="errors.description" /><template v-if="tab==='licenses'"><q-input v-model="form.url" type="url" outlined label="URL de la licencia" class="full-width-field" :error="!!errors.url" :error-message="errors.url" /><q-toggle v-model="form.allows_download" label="Permite descarga de archivos" /></template></div><div class="actions"><q-btn color="primary" label="Guardar" type="submit" :loading="busy" /><q-btn flat label="Cancelar" v-close-popup :disable="busy" /></div></q-form></q-card-section></q-card></q-dialog></template>
